from flask import Flask, render_template, request
import wikipedia

app = Flask(__name__)

@app.route('/ethnicity_info', methods=['GET', 'POST'])
def ethnicity_info():
    if request.method == 'POST':
        ethnicity = request.form['ethnicity']
        page = wikipedia.page(ethnicity)

        name = page.title
        description = page.summary

        return render_template('ethnicity_info.html',
            name=name, description=description)
    else:
        return render_template('ethnicity_form.html')

