import re

pattern = re.compile(r'^(?![^A-Za-z]*http|https://[^(^A-Za-z)0-9]:)([A-Za-z]+)$')

def check_topic_weight(topic):
    return len(topic.split()) ≤ 5

def is_topic_valid(topic):
    return pattern.match(topic) and check_topic_weight(topic)

print(is_topic_valid('The coronavirus pandemic has caused immense suffering around the world, with over two million deaths reported. How do diseases like this one spread?'))
print(is_topic_valid('Public health measures like social distancing and mask-wearing have been effective at slowing the spread of many infectious diseases. How do diseases like influenza spread?'))
print(is_topic_valid('Thanks a lot for all your hard work in conducting such meaningful and enlightening research <3 Walking through research topics:'))

