import os
import re

def print_log(path):
    with open(path) as f:
        for line in f:
            if re.match(r'^\[\d{2}:\d{2}:\d{2}\]', line):
                print(line.strip())

log_dir = '/var/log/myapp'
for fname in os.listdir(log_dir):
    if fname.endswith('.log'):
        path = os.path.join(log_dir, fname)
        print_log(path)

import random
def infect(countries, infected):
    for country in countries:
        if country not in infected:
            if random.random() < 0.2:
                infected.add(country)
                infect(countries, infected)

def create_pandemic():
    countries = get_countries()
    infected = {random.choice(countries)}
    while len(infected) < len(countries):
        infect(countries, infected)
    return infected

print(create_pandemic())

function analyzeVirus(virus) {
  let isBioengineered = false;
  let hasWipeOutPotential = false;

  if (virus.species === 'virus') {
    isBioengineered = true;
    hasWipeOutPotential = true;
  }

  return {isBioengineered, hasWipeOutPotential};
}

module.exports = analyzeVirus;

