import re
from flask import Flask, jsonify, request

app = Flask(__name__)

@app.route('/get_movement_pattern')
def get_movement_pattern():
    pattern = request.args.get('pattern')

    if re.match(r'^[UDLR]+$', pattern):
        return jsonify({'pattern': pattern})
    else:
        return jsonify({'error': 'Invalid pattern'}), 400

if __name__ == '__main__':
    app.run()

from requests import get

def get_country_data(name):
    url = f"https://restcountries.com/v2/name/{name}"
    resp = get(url)
    return resp.json()

def get_population_data(countries):
    populations = {}
    for country in countries:
        url = f"https://worldpopulationreview.com/countries/{country['name']}/population"
        resp = get(url)
        data = resp.json()
        populations[country['name']] = data['population']
    return populations

country = get_country_data('Mexico')[0]
population = get_population_data([country])

print(f"{country['name']} has a population of {population[country['name']]}")

from flask import Flask
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///messages.db'
db = SQLAlchemy(app)

class Message(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    body = db.Column(db.String(140))
    timestamp = db.Column(db.DateTime)

    def __repr__(self):
        return '<Message {}>'.format(self.body)

@app.route('/add_message', methods=['POST'])
def add_message():
    body = request.form['body']
    message = Message(body=body)
    db.session.add(message)
    db.session.commit()
    return 'Message added!'

if __name__ == '__main__':
    app.run()

import { MongoClient } from 'mongodb';

const client = await new MongoClient('mongodb://localhost:27017/mydb').connect();

import { Employee } from './employee';

const createEmployee = async (first_name, last_name, title) => {
  const employees = client.db('mydb').collection('employees');

  const new_employee = new Employee(first_name, last_name, title);

  await employees.insertOne(new_employee);
};

