    &lt;ul&gt;
    {% for review in reviews %}
        &lt;li&gt;**Rating: {{ review.rating }}/5&lt;/li&gt;
        &lt;li&gt;**Review: {{ review.body|e }}&lt;/li&gt;
    {% endfor %}
