    return template.render(reviews=reviews)

from jinja2 import Template

def render_posts(posts):
    template = Template("<h3>{{ post.title }}</h3><p>{{ post.content }}</p>", autoescape=True)
    return ''.join(template.render(post=post) for post in posts)

